method.description:
The [member multimesh] instance a collision was with, from the collider's [param body] and [param shape] index as a raycast or contact reports them, or -1.
[codeblock]
var hit := space.intersect_ray(query)
if hit.collider is MultiMeshBody3D:
    var bollard: int = hit.collider.get_instance(hit.rid, hit.shape)
[/codeblock]
